/**
 * @event
 * @name scwin.grd_calendarWeekList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_calendarWeekList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_calendarWeekList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_calendarWeekList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_dataSet('${schedule.applNo}','${schedule.confroomTpCd}', '${schedule.irTpCd}', '${schedule.calndDd}', '${fn:substring(schedule.useStrtDdtm, 8, 10)}', '${fn:substring(schedule.useEndDdtm, 8, 10)}', '${schedule.acptNm}', '${schedule.acptEmail}', '${schedule.reservStatTpCd}'); (EL 미해석) */
        if (typeof scwin.schedules2 === 'function') { await scwin.schedules2(r["code"]); } else { console.error('[sdd] 행 동작 미정의: scwin.schedules2 (열 월)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.schedules2'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_calendarWeekList.oncellclick' });
    }
};


